package ru.pulsedoma.issues;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import static ru.pulsedoma.issues.CaseExchangeService.*;
import static ru.pulsedoma.issues.OperationsTypes.*;

@Service
public class OperationsMonitoringService {
 private final JdbcTemplate db;private final CaseWorkAccess access;private final OperationsNotifications notifications;
 public OperationsMonitoringService(JdbcTemplate db,CaseWorkAccess access,OperationsNotifications notifications){this.db=db;this.access=access;this.notifications=notifications;}
 private void manager(String house,String user){if(!access.manager(house,user))throw missing();}
 public Map<String,Object> policy(String house,String user){manager(house,user);var rows=db.queryForList("SELECT p.* FROM house_reminder_policies p JOIN organization_houses h ON h.organization_id=p.source_organization_id AND h.house_id=p.house_id WHERE p.house_id=? AND h.status='ACTIVE'",house);return rows.isEmpty()?Map.of():rows.getFirst();}
 @Transactional public Map<String,Object> policy(String house,OperationsRequests.Policy r,String user){manager(house,user);if(!access.manager(house,r.managerId()))throw invalid("Выберите действующего руководителя УК этого дома");var old=db.queryForList("SELECT revision FROM house_reminder_policies WHERE house_id=?",house);if((old.isEmpty()?0:rev(old.getFirst()))!=r.revision())throw conflict();String org=db.queryForObject("SELECT organization_id FROM uk_admin_houses WHERE house_id=? AND user_id=? AND access_status='ACTIVE' LIMIT 1",String.class,house,user);db.update("INSERT INTO house_reminder_policies(house_id,source_organization_id,enabled,before_hours,repeat_hours,escalate_hours,manager_id,revision,updated_by,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?) ON CONFLICT(house_id) DO UPDATE SET source_organization_id=excluded.source_organization_id,enabled=excluded.enabled,before_hours=excluded.before_hours,repeat_hours=excluded.repeat_hours,escalate_hours=excluded.escalate_hours,manager_id=excluded.manager_id,revision=house_reminder_policies.revision+1,updated_by=excluded.updated_by,updated_at=excluded.updated_at",house,org,r.enabled()?1:0,r.beforeHours(),r.repeatHours(),r.escalateHours(),r.managerId(),1,user,now());db.update("INSERT INTO operations_history(id,house_id,entity_id,action,note,snapshot_json,actor_id,created_at) VALUES (?,?,?,'POLICY_CHANGED',?,'{}',?,?)",id(),house,house,r.reason(),user,now());return policy(house,user);}
 public record Deadline(String entity,String caseId,String house,String due,DeadlineKind kind,String worker){}
 public List<Deadline> deadlines(String house){var result=new ArrayList<Deadline>();for(var c:db.queryForList("SELECT id,responsible_user_id,due_at FROM resident_cases WHERE internal_work=0 AND house_id=? AND due_at IS NOT NULL AND status NOT IN ('CLOSED','WAITING_RESIDENT','RESULT_PROPOSED')",house))result.add(new Deadline(s(c,"id"),s(c,"id"),house,s(c,"due_at"),DeadlineKind.CASE_STEP,s(c,"responsible_user_id")));
 String[][] sources={{"case_work_orders","due_at","assignee_id","state NOT IN ('ACCEPTED','CANCELLED')","WORK_ORDER"},{"exchange_packets","due_at","NULL","state NOT IN ('REVIEWED','CANCELLED')","EXCHANGE_PACKET"},{"case_handoffs","due_at","NULL","state NOT IN ('RESPONDED','CANCELLED')","LEGACY_HANDOFF"},{"billing_corrections","due_at","NULL","state NOT IN ('VERIFIED','REFUSAL_REVIEWED','CANCELLED')","BILLING_CORRECTION"}};
 for(var source:sources)for(var r:db.queryForList("SELECT t.id,t.case_id,t."+source[1]+" AS due,"+(source[2].equals("NULL")?"NULL":"t."+source[2])+" AS worker FROM "+source[0]+" t JOIN resident_cases c ON c.id=t.case_id WHERE c.house_id=? AND c.status<>'CLOSED' AND t."+source[1]+" IS NOT NULL AND t."+source[3],house))result.add(new Deadline(s(r,"id"),s(r,"case_id"),house,s(r,"due"),DeadlineKind.valueOf(source[4]),s(r,"worker")));
 return result;}
 @Transactional public int scan(){int queued=0;for(var p:db.queryForList("SELECT p.* FROM house_reminder_policies p JOIN organization_houses h ON h.house_id=p.house_id AND h.organization_id=p.source_organization_id WHERE p.enabled=1 AND h.status='ACTIVE'")){String house=s(p,"house_id"),org=s(p,"source_organization_id"),manager=s(p,"manager_id");if(!access.manager(house,manager))continue;long before=((Number)p.get("before_hours")).longValue()*3600,repeat=((Number)p.get("repeat_hours")).longValue()*3600,escalate=((Number)p.get("escalate_hours")).longValue()*3600;
 for(var d:deadlines(house)){Instant due=Instant.parse(d.due());if(due.isAfter(Instant.now().plusSeconds(before)))continue;var c=db.queryForList("SELECT number,responsible_user_id FROM resident_cases WHERE id=?",d.caseId()).getFirst();String body=(due.isBefore(Instant.now())?"Прошёл срок":"Приближается срок")+" по обращению №"+c.get("number")+". Проверьте рабочий кабинет. Личные материалы доступны только при действующем допуске.";Set<String> targets=new HashSet<>();if(c.get("responsible_user_id")!=null)targets.add(s(c,"responsible_user_id"));if(d.worker()!=null)targets.add(d.worker());for(var f:db.queryForList("SELECT deputy_id FROM case_followup WHERE case_id=? AND source_organization_id=? AND deputy_id IS NOT NULL",d.caseId(),org))targets.add(s(f,"deputy_id"));String dedupe="deadline:"+d.kind()+":"+d.entity()+":"+d.due()+":"+(Instant.now().getEpochSecond()/repeat);
 for(String user:targets){notifications.enqueue(user,house,d.caseId(),NotificationKind.REMINDER,d.entity(),0,dedupe,body,org,d.kind(),d.due());queued++;}
 if(due.isBefore(Instant.now().minusSeconds(escalate))&&!access.exists("SELECT count(*) FROM automatic_case_escalations WHERE case_id=? AND entity_id=? AND due_at=? AND manager_id=?",d.caseId(),d.entity(),d.due(),manager)){String escalation=id();db.update("INSERT INTO case_escalations(id,case_id,target_id,state,reason,created_by,created_at,updated_at) VALUES (?,?,?,'OPEN',?,?,?,?)",escalation,d.caseId(),manager,"Автоматическая эскалация: превышен согласованный срок "+d.kind()+" по обращению №"+c.get("number"),manager,now(),now());db.update("INSERT INTO automatic_case_escalations(case_id,entity_id,due_at,manager_id,escalation_id) VALUES (?,?,?,?,?)",d.caseId(),d.entity(),d.due(),manager,escalation);db.update("UPDATE resident_cases SET revision=revision+1,updated_at=? WHERE id=?",now(),d.caseId());db.update("INSERT INTO control_history(id,house_id,case_id,action,note,snapshot_json,actor_id,created_at) VALUES (?,?,?,'ESCALATED',?,'{}',?,?)",id(),house,d.caseId(),"Автоматическая эскалация просроченного шага",manager,now());notifications.enqueue(manager,house,d.caseId(),NotificationKind.ESCALATION,escalation,0,"escalation:"+escalation,"Нужна реакция руководителя: просрочен шаг по обращению №"+c.get("number")+". Откройте контроль обращений.",org,d.kind(),d.due());queued++;}}
 for(var w:db.queryForList("SELECT w.* FROM mass_work_orders w JOIN house_mass_problems p ON p.id=w.problem_id WHERE p.house_id=? AND p.source_organization_id=? AND p.state='ACTIVE' AND w.state NOT IN ('ACCEPTED','CANCELLED') AND w.due_at IS NOT NULL",house,org)){String due=s(w,"due_at");Instant time=Instant.parse(due);if(time.isAfter(Instant.now().plusSeconds(before)))continue;String key="shared:"+w.get("id")+":"+due+":"+(Instant.now().getEpochSecond()/repeat);notifications.enqueue(s(w,"worker_id"),house,null,NotificationKind.REMINDER,s(w,"id"),rev(w),key,"Проверьте срок общей работы дома. Подробности и возможность отчёта — в разделе общих проблем.",org,DeadlineKind.SHARED_WORK,due);if(time.isBefore(Instant.now().minusSeconds(escalate)))notifications.enqueue(manager,house,null,NotificationKind.ESCALATION,s(w,"id"),rev(w),key+":manager","Нужна реакция руководителя: просрочена общая работа дома. Откройте раздел общих проблем.",org,DeadlineKind.SHARED_WORK,due);}
 for(var v:db.queryForList("SELECT v.*,s.starts_at,c.author_id,c.number FROM case_visits v JOIN visit_slots s ON s.id=v.selected_slot_id JOIN resident_cases c ON c.id=v.case_id WHERE c.house_id=? AND c.status<>'CLOSED' AND v.state='CONFIRMED' AND v.source_organization_id=? AND datetime(s.starts_at)>datetime('now') AND datetime(s.starts_at)<=datetime('now',? )",house,org,"+"+((Number)p.get("before_hours")).intValue()+" hours")){for(String user:List.of(s(v,"author_id"),s(v,"worker_id")))notifications.enqueue(user,house,s(v,"case_id"),NotificationKind.VISIT,s(v,"id"),rev(v),"visit:"+v.get("id")+":"+v.get("starts_at"),"Напоминание о согласованном визите по обращению №"+v.get("number")+". Время и возможность переноса — в карточке обращения.",org,DeadlineKind.VISIT,s(v,"starts_at"));}
 }return queued;}
 public Map<String,Object> analytics(String house,String user){manager(house,user);var out=new LinkedHashMap<String,Object>();out.put("generatedAt",now());out.put("definition","Первое действие — сообщение, назначение или обновление не от автора. Решение — подтверждение жителя. Средние рассчитаны только по случаям с соответствующим событием; это не нормативный SLA.");out.put("summary",db.queryForList("SELECT count(*) AS total,sum(CASE WHEN status<>'CLOSED' THEN 1 ELSE 0 END) AS active,sum(CASE WHEN status='CLOSED' THEN 1 ELSE 0 END) AS confirmed,sum(CASE WHEN status<>'CLOSED' AND responsible_user_id IS NULL THEN 1 ELSE 0 END) AS unassigned FROM resident_cases WHERE internal_work=0 AND house_id=?",house).getFirst());out.put("byStatus",db.queryForList("SELECT status,count(*) AS count FROM resident_cases WHERE internal_work=0 AND house_id=? GROUP BY status",house));out.put("byKind",db.queryForList("SELECT kind,count(*) AS count FROM resident_cases WHERE internal_work=0 AND house_id=? GROUP BY kind",house));out.put("workload",db.queryForList("SELECT coalesce(u.display_name,'Очередь без ответственного') AS employee,count(*) AS active FROM resident_cases c LEFT JOIN users u ON u.id=c.responsible_user_id WHERE c.house_id=? AND c.internal_work=0 AND c.status<>'CLOSED' GROUP BY c.responsible_user_id",house));out.put("response",db.queryForList("SELECT count(*) AS observations,round(avg((julianday(first_at)-julianday(created_at))*24),2) AS average_hours FROM (SELECT c.created_at,min(e.created_at) AS first_at FROM resident_cases c JOIN case_events e ON e.case_id=c.id AND e.actor_id<>c.author_id AND e.type IN ('MESSAGE','UPDATED','ASSIGNED') WHERE c.house_id=? GROUP BY c.id)",house).getFirst());out.put("resolution",db.queryForList("SELECT count(*) AS observations,round(avg((julianday(confirmed_at)-julianday(created_at))*24),2) AS average_hours FROM (SELECT c.created_at,max(e.created_at) AS confirmed_at FROM resident_cases c JOIN case_events e ON e.case_id=c.id AND e.type='CONFIRMED' WHERE c.house_id=? AND c.status='CLOSED' GROUP BY c.id)",house).getFirst());out.put("reopened",db.queryForObject("SELECT count(*) FROM case_events e JOIN resident_cases c ON c.id=e.case_id WHERE c.house_id=? AND e.type='REOPENED'",Integer.class,house));var deadlines=deadlines(house);out.put("overdueSteps",deadlines.stream().filter(d->Instant.parse(d.due()).isBefore(Instant.now())).count());out.put("overdueCases",deadlines.stream().filter(d->Instant.parse(d.due()).isBefore(Instant.now())).map(Deadline::caseId).distinct().count());out.put("organizationResponses",db.queryForList("SELECT json_extract(p.channel_snapshot,'$.participant_type') AS participant,count(*) AS packets,sum(CASE WHEN p.state IN ('SENT','RECEIVED') THEN 1 ELSE 0 END) AS waiting,round(avg((julianday(a.answered_at)-julianday(s.sent_at))*24),2) AS average_answer_hours FROM exchange_packets p JOIN resident_cases c ON c.id=p.case_id LEFT JOIN (SELECT packet_id,min(created_at) AS sent_at FROM exchange_history WHERE action='PACKET_SENT' GROUP BY packet_id) s ON s.packet_id=p.id LEFT JOIN (SELECT packet_id,min(published_at) AS answered_at FROM exchange_replies WHERE published_at IS NOT NULL GROUP BY packet_id) a ON a.packet_id=p.id WHERE c.house_id=? AND p.state NOT IN ('DRAFT','READY') GROUP BY json_extract(p.channel_snapshot,'$.participant_type')",house));out.put("massWorkReworks",db.queryForObject("SELECT count(*) FROM operations_history WHERE house_id=? AND action='WORK_UPDATED' AND json_extract(snapshot_json,'$.state')='REWORK'",Integer.class,house));out.put("sharedWorkOverdue",db.queryForObject("SELECT count(*) FROM mass_work_orders w JOIN house_mass_problems p ON p.id=w.problem_id WHERE p.house_id=? AND w.state NOT IN ('ACCEPTED','CANCELLED') AND datetime(w.due_at)<datetime('now')",Integer.class,house));out.put("notifications",db.queryForList("SELECT kind,count(*) AS queued,sum(CASE WHEN sent_at IS NOT NULL THEN 1 ELSE 0 END) AS delivered,sum(CASE WHEN attempts>0 AND sent_at IS NULL AND cancelled_at IS NULL THEN 1 ELSE 0 END) AS retrying FROM operations_notifications WHERE house_id=? GROUP BY kind",house));return out;}
}
